local worldBossComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.WorldBossComponent)

---@class WorldBossModelProxy
local WorldBossModelProxy = Class("WorldBossModelProxy")

------------------Constructor & DeConstructor---------------

function WorldBossModelProxy.new()
    local obj = WorldBossModelProxy.New()
    obj.model = {}
    obj.cardSkinModel = {}
    obj:ReloadData()
    return obj
end

function WorldBossModelProxy:Release()
    self.model:Release()
    self.model = nil
end

-------------------public function-----------------------

function WorldBossModelProxy:ReloadData()
    local planId = worldBossComponent:GetCurBossPlanId()
    self.model = QuestConfMgr:GetInstance():GetWorldBossBossVo(planId)
    self.cardSkinModel = CfUtils.GetCfVo(AutoIds.IdSetting113, "CardSkinVo", self.model.skinId)
end

-------------------Properties-------------------

function WorldBossModelProxy:SkinId()
    return self.model.skinId
end

function WorldBossModelProxy:Name()
    return self.cardSkinModel.name
end

return WorldBossModelProxy